// Regenerates src/install/searxng-assets.ts from install-searxng.sh and requirements.lock (the
// agent release tarball carries only dist/, so the installer writes them out from there).
//   node scripts/linux/searxng/gen-assets.mjs
// tests/install/searxng.test.ts fails when the generated file and these sources differ.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..", "..");
const lines = (name) => readFileSync(join(here, name), "utf8").replace(/\n$/, "").split("\n").map((l) => `  ${JSON.stringify(l)},`).join("\n");
export function render() {
  return `// Copyright (c) 2025 EdgeCoder
// SPDX-License-Identifier: BUSL-1.1

// GENERATED by scripts/linux/searxng/gen-assets.mjs from scripts/linux/searxng/install-searxng.sh and
// requirements.lock. Do not edit; edit those and run: node scripts/linux/searxng/gen-assets.mjs

/** scripts/linux/searxng/install-searxng.sh */
export const SEARXNG_INSTALL_SCRIPT = [
${lines("install-searxng.sh")}
].join("\\n") + "\\n";

/** scripts/linux/searxng/requirements.lock */
export const SEARXNG_REQUIREMENTS_LOCK = [
${lines("requirements.lock")}
].join("\\n") + "\\n";
`;
}
if (process.argv[1] === fileURLToPath(import.meta.url)) writeFileSync(join(root, "src", "install", "searxng-assets.ts"), render());
